#!/usr/bin/env python3
"""Evaluation script for Gmail Triage Workflow task."""

import json
import os
from pathlib import Path

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def evaluate():
    results = {
        'passed': True,
        'checks': [],
        'errors': []
    }

    # Load expected data
    expected_labels = {
        'm1': {'Urgent', 'School', 'Needs Reply'},
        'm2': {'Receipt / Billing'},
        'm3': {'Clubs', 'Needs Reply'},
        'm4': {'Admin / Accounts', 'Urgent'},
        'm5': {'School', 'Urgent', 'Needs Reply'},
        'm6': {'Clubs', 'Needs Reply'}
    }

    emails_needing_reply = {'m1', 'm3', 'm4', 'm5', 'm6'}

    # Check triage_results.json
    triage_path = Path('workspace/triage_results.json')
    if not triage_path.exists():
        results['passed'] = False
        results['errors'].append('triage_results.json not found')
        return results

    triage = load_json(triage_path)

    # Check labels for each email
    for email_id, expected in expected_labels.items():
        if email_id not in triage:
            results['passed'] = False
            results['errors'].append(f'{email_id}: missing from triage results')
            continue

        actual_labels = set(triage[email_id].get('labels', []))
        if expected != actual_labels:
            results['passed'] = False
            results['errors'].append(
                f'{email_id}: labels mismatch. Expected {expected}, got {actual_labels}'
            )
        else:
            results['checks'].append(f'{email_id}: labels correct')

    # Check drafts directory
    drafts_path = Path('workspace/drafts')
    if not drafts_path.exists():
        results['passed'] = False
        results['errors'].append('drafts directory not found')
        return results

    # Check that drafts exist for emails needing replies
    for email_id in emails_needing_reply:
        draft_file = drafts_path / f'{email_id}_draft.json'
        if not draft_file.exists():
            results['passed'] = False
            results['errors'].append(f'{email_id}: draft file not found')
            continue

        draft = load_json(draft_file)

        # Check draft has required fields
        if 'to' not in draft or 'subject' not in draft or 'body' not in draft:
            results['passed'] = False
            results['errors'].append(f'{email_id}: draft missing required fields')
            continue

        # Check draft is not empty
        if not draft['body'] or len(draft['body'].strip()) < 20:
            results['passed'] = False
            results['errors'].append(f'{email_id}: draft body too short or empty')
            continue

        results['checks'].append(f'{email_id}: draft exists and valid')

    # Check that m2 (Amazon) does NOT have a draft (no reply needed)
    m2_draft = drafts_path / 'm2_draft.json'
    if m2_draft.exists():
        results['passed'] = False
        results['errors'].append('m2: should not have a draft (no reply needed)')
    else:
        results['checks'].append('m2: correctly has no draft')

    # Check no sent flag
    for email_id in triage:
        if triage[email_id].get('sent', False):
            results['passed'] = False
            results['errors'].append(f'{email_id}: should not be marked as sent')
        else:
            results['checks'].append(f'{email_id}: correctly not sent')

    return results

if __name__ == '__main__':
    results = evaluate()
    print(json.dumps(results, indent=2))
    exit(0 if results['passed'] else 1)
EOFEVAL\n",
